FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'economic_indicators_selected') AND w.code = 'ISO-59020-04' AND s.code = 'ISO-59020';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'additional_indicators', 'Zusätzliche Indikatoren (Annex B / Tabelle B.1; je Indikator: Bezeichnung, Definition, Wert, Einheit)', 'json', NULL, false, '§7.3.1, §7.3.2, Annex B', 'Plan 3: Zeilen je zusätzlichem Indikator („The core circularity indicators can be supplemented by additional circularity indicators“); Anzahl → additional_indicators_count (ISO-59020-04-D11). Das Textfeld additional_indicator bleibt (iso59020-D-5).', 'imported_unverified', '             The core circularity indicators can be supplemented by additional circularity indicators to meet the goal and
             scope of the circularity measurement and assessment. A materiality approach can be valuable to prioritize
             and select relevant indicators for the measurement. Annex B provides examples of additional indicators. —              The core circularity indicators can be supplemented by the additional indicators or recommendations
             addressed in Annex B. However, other indicators can still be needed such as the following:', 'register', '{"title":"Zusätzliche Indikatoren (additional indicators, §7.3.2 / Annex B)","subtitle":"Je zusätzlichem Indikator eine Zeile — Tabelle B.1 als Vorschlagsliste, eigene Indikatoren frei","add_label":"+ zusätzlicher Indikator","placement":"section","columns":[{"key":"name","label":"Indikator","type":"text","required":true,"datalist":["B.3.2 Per cent designed reusability rate of the outflow","B.3.3 Per cent designed recyclability rate of the outflow","B.4.2 Per cent energy recovered from residual, non-renewable and non-recoverable resource outflows","B.4.3 Energy intensity","B.5.2 Nutrient extraction from discharged water","B.5.3 Water intensity","B.6.3 Net value added","B.6.4 Value per mass","B.6.5 Resource productivity","B.6.6 Genuine process indicator"],"aria_label":"Bezeichnung des zusätzlichen Indikators"},{"key":"definition","label":"Definition / Berechnung","type":"text","aria_label":"Definition oder Berechnungsvorschrift"},{"key":"value","label":"Wert","type":"number","aria_label":"Wert des zusätzlichen Indikators"},{"key":"unit","label":"Einheit","type":"text","aria_label":"Einheit des zusätzlichen Indikators"}],"footer":["additional_indicators_count"],"note":"             The core circularity indicators can be supplemented by additional circularity indicators to meet the goal and\n             scope of the circularity measurement and assessment. A materiality approach can be valuable to prioritize\n             and select relevant indicators for the measurement. Annex B provides examples of additional indicators. Das Einzelfeld additional_indicator bleibt (iso59020-D-5)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'additional_indicators') AND w.code = 'ISO-59020-04' AND s.code = 'ISO-59020';
