SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'additional_indicators_count', 'Anzahl zusätzlicher Indikatoren', 'number', NULL, false, '§7.3.2, Annex B', 'Plan 3: Ausgabe der Gleichung ISO-59020-04-D11 — count_rows über additional_indicators.', 'imported_unverified', '             The core circularity indicators can be supplemented by the additional indicators or recommendations
             addressed in Annex B. However, other indicators can still be needed such as the following:', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'additional_indicators_count') AND w.code = 'ISO-59020-04' AND s.code = 'ISO-59020';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'inflows', 'Ressourcenzuflüsse X (je Zufluss: mTI, mREUI, mRECI, mRENI; Anteile nach A.1 – A.3, linearer Rest, 100 %-Bilanz)', 'json', NULL, false, 'A.2.1 – A.2.4, Formula (A.1) – (A.3)', 'Plan 3: Zeilen je Ressourcenzufluss X („Different types of inflow resources … should be measured and recorded separately“) mit den Formeln (A.1) – (A.3) je Zeile und dem linearen Rest (A.2.1: „subtracting the circular inflows from 100 %“); Σ / massengewichtete Anteile → ISO-59020-05-D1 … D11. Die Einzelfelder bleiben (iso59020-D-6 … D-10).', 'imported_unverified', '             Different types of inflow resources or those that have different circularity characteristics (e.g. have different
             amounts of recycled content) should be measured and recorded separately. In Figure A.1, the “X” in inflow
             (X) represents a specific resource inflow. —              The calculation of the circularity indicators for each inflow can be performed and reported individually
             or can be aggregated, based on the goal of the circularity measurement and assessment and allowing
             for attributed content from a mass balance chain of custody model as defined in ISO 22095. Maintaining
             separate calculations for each resource inflow (X) enables characteristics such as per cent reused content
             to be tracked through use and processing stages within the system in focus. It also provides flexibility in
             applying complementary methods for circularity assessment.', 'register', '{"title":"Ressourcenzuflüsse X (resource inflows, Annex A.2)","subtitle":"Je Zufluss X eine Zeile: Gesamtmasse mTI(X) und die Massen der drei zirkulären Anteile mREUI / mRECI / mRENI (kg); die Anteile nach Formula (A.1) – (A.3) und der lineare Rest (100 % − zirkulär) werden je Zeile berechnet","add_label":"+ Zufluss","placement":"section","columns":[{"key":"label","label":"Zufluss X","type":"text","required":true,"aria_label":"Bezeichnung des Zuflusses X"},{"key":"m_ti","label":"mTI(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Gesamtmasse Eingangsmaterial des Zuflusses X"},{"key":"m_reui","label":"mREUI(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Masse wiederverwendeter Komponenten und Produkte des Zuflusses X"},{"key":"m_reci","label":"mRECI(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Masse recycelten Materials des Zuflusses X"},{"key":"m_reni","label":"mRENI(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Masse erneuerbaren Materials des Zuflusses X"},{"key":"pct_reui","label":"%REUI(X) (A.1)","type":"derived","expr":"m_reui / m_ti * 100"},{"key":"pct_reci","label":"%RECI(X) (A.2)","type":"derived","expr":"m_reci / m_ti * 100"},{"key":"pct_reni","label":"PRENI(X) (A.3)","type":"derived","expr":"m_reni / m_ti * 100"},{"key":"pct_linear","label":"linear (%)","type":"derived","expr":"100 - pct_reui - pct_reci - pct_reni"},{"key":"m_linear","label":"linear (kg)","type":"derived","expr":"m_ti - m_reui - m_reci - m_reni"},{"key":"balanced","label":"100 %-Bilanz","type":"derived","expr":"if(m_reui + m_reci + m_reni <= m_ti, 1, 0)","display":"badge","value_labels":{"0":"zirkuläre Massen übersteigen mTI(X)","1":"bilanziert (zirkulär ≤ Gesamt)"}}],"footer":["inflows_count","m_ti_total","pct_reui_agg","pct_reci_agg","pct_reni_agg","pct_linear_agg","inflows_unbalanced"],"note":"             Different types of inflow resources or those that have different circularity characteristics (e.g. have different\n             amounts of recycled content) should be measured and recorded separately. In Figure A.1, the “X” in inflow\n             (X) represents a specific resource inflow.              These four types of content are intended to be mutually exclusive and add up to represent 100 % of the\n             resource inflow (see Figure A.1). The first three types (recycled, reused and virgin, renewable content) are\n             considered as circular; whereas the fourth type (virgin, non-renewable content) is the remaining portion\n             that is from a non-circular source. The non-circular (linear) inflow can be calculated by subtracting the\n             circular inflows from 100 %. For a material to be described as a “renewable material”, it shall adhere to the Die Fußzeile aggregiert massengewichtet (Σ Masse des Anteils / Σ mTI — Anhang G.2 EXAMPLE c, iso59020-J-1). Die Einzelfelder mTI_X / mREUI_X / mRECI_X / mRENI_X / pct_linear_inflow bleiben (iso59020-D-6 … D-10); Gleichungen A.1 – A.3 und CR-011 … CR-014 → iso59020-R-1 / G-3."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'inflows') AND w.code = 'ISO-59020-05' AND s.code = 'ISO-59020';
