SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'inflows_count', 'Anzahl erfasster Zuflüsse X', 'number', NULL, false, 'A.2.1', 'Plan 3: Ausgabe der Gleichung ISO-59020-05-D1 — count_rows über inflows.', 'imported_unverified', '             Different types of inflow resources or those that have different circularity characteristics (e.g. have different
             amounts of recycled content) should be measured and recorded separately. In Figure A.1, the “X” in inflow
             (X) represents a specific resource inflow.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'inflows_count') AND w.code = 'ISO-59020-05' AND s.code = 'ISO-59020';
