SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'm_ti_total', 'Σ mTI(X) — Gesamtmasse aller Zuflüsse', 'number', 'kg', false, 'A.2.1, A.1', 'Plan 3: Ausgabe der Gleichung ISO-59020-05-D2 — sum_rows über inflows.m_ti („absolute values with units should also be documented“, A.1).', 'imported_unverified', '             Many of the indicators provide percentage values (e.g. “average per cent reused content of an inflow”).
             However, in calculating these percentages, absolute values with units should also be documented. This
             allows the scale to be properly assessed and data to be aggregated.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_ti_total') AND w.code = 'ISO-59020-05' AND s.code = 'ISO-59020';
