SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'm_reui_total', 'Σ mREUI(X)', 'number', 'kg', false, 'A.2.2', 'Plan 3: Ausgabe der Gleichung ISO-59020-05-D3 — sum_rows über inflows.m_reui.', 'imported_unverified', '             The calculation of the circularity indicator is performed by applying Formula (A.1):

                                    mREUI( X )              
                      %REUI( X ) =                           ⋅100                                                                     (A.1)
                                    mTI X                   
                                        ( )                 
             where

                       %REUI( X )                     is the average reused content of an inflow (X), in %;

                       mREUI( X )                     is the mass of reused components and products of an inflow (X), in kg or other mass unit;

                       mTI( X )                       is the mass of total input material of an inflow (X), in kg or other mass unit.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_reui_total') AND w.code = 'ISO-59020-05' AND s.code = 'ISO-59020';
