SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'F'), 'm_reci_total', 'Σ mRECI(X)', 'number', 'kg', false, 'A.2.3', 'Plan 3: Ausgabe der Gleichung ISO-59020-05-D4 — sum_rows über inflows.m_reci.', 'imported_unverified', '             The calculation of the circularity indicator is performed by applying Formula (A.2):

                                    mRECI( X )              
                      %RECI( X ) =                           ⋅100                                                                     (A.2)
                                    mTI X                   
                                        ( )                 
             where

                       %RECI( X ) is the average recycled content of an inflow (X), in %;

                       mRECI( X ) is the mass of recycled material of an inflow (X), in kg or other mass unit;

                       mTI( X )              is the mass of total input material of an inflow (X), in kg or other mass unit.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_reci_total') AND w.code = 'ISO-59020-05' AND s.code = 'ISO-59020';
