INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'outflows', 'Ressourcenabflüsse X (je Abfluss: mTO, mREUO, mRECO, mRENO, tLP, tIALP; Anteile nach A.4 – A.7, linearer Rest, 100 %-Bilanz)', 'json', NULL, false, 'A.3.1 – A.3.5, Formula (A.4) – (A.7)', 'Plan 3: Zeilen je Ressourcenabfluss X („The circularity indicators for each outflow can be calculated and reported individually or they can be aggregated“) mit den Formeln (A.4) – (A.7) je Zeile, dem A.3.4-Schalter für nicht rückverfolgbare Recyclingdaten (0 %) und dem linearen Rest (A.3.1); Σ / massengewichtete Anteile → ISO-59020-06-D1 … D12. Die Einzelfelder bleiben (iso59020-D-11 … D-17).', 'imported_unverified', '             The following three core circularity indicators are intended to represent outflows that are mutually
             exclusive and represent the circular outflows:
             — components and products that are reused (see A.3.3);
             — per cent recycled material derived from outflow (see A.3.4),
             — products and materials for renewable recirculation (see A.3.5).
             The remaining outflows are considered as linear and do not count towards circularity. The linear (non-
             circular) outflow can be calculated by subtracting the circular outflows from 100 %. —              The sum of the circular outflows and the remaining non-circular outflows represent 100 % of the resource
             outflows from the system in focus, see Figure A.2. The resource outflow circularity indicators specified in
             A.3.3, A.3.4 and A.3.5 shall be calculated and documented. In cases where the circularity indicator is not
             relevant, it can be counted at value zero. The circularity indicators for each outflow can be calculated and
             reported individually or they can be aggregated, based on goal and scope.', 'register', '{"title":"Ressourcenabflüsse X (resource outflows, Annex A.3)","subtitle":"Je Abfluss X eine Zeile: Gesamtmasse mTO(X), wiederverwendete / recycelte / biologisch rezirkulierte Masse (kg), optional Lebensdauer tLP / tIALP (A.3.2); die Anteile nach Formula (A.4) – (A.7) und der lineare Rest werden je Zeile berechnet; ohne rückverfolgbare Recyclingdaten gilt 0 % (A.3.4)","add_label":"+ Abfluss","placement":"section","columns":[{"key":"label","label":"Abfluss X","type":"text","required":true,"aria_label":"Bezeichnung des Abflusses X"},{"key":"m_to","label":"mTO(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Gesamtmasse des Abflusses X"},{"key":"m_reuo","label":"mREUO(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Masse des wiederverwendeten Abflusses X"},{"key":"traceable_recycling","label":"Recyclingdaten rückverfolgbar","type":"boolean","discriminator":true,"aria_label":"Rückverfolgbare Recyclingdaten für den Abfluss X vorhanden (A.3.4)"},{"key":"m_reco","label":"mRECO(X)","type":"number","unit":"kg","required":true,"min":0,"visible_when":"traceable_recycling == true","aria_label":"Masse recycelten Materials aus dem Abfluss X"},{"key":"m_reno","label":"mRENO(X)","type":"number","unit":"kg","required":true,"min":0,"aria_label":"Masse des Abflusses X in erneuerbarer Rezirkulation"},{"key":"t_lp","label":"tLP(X)","type":"number","unit":"a","min":0,"aria_label":"Lebensdauer des Produkts oder Materials X (optional, A.3.2)"},{"key":"t_ialp","label":"tIALP(X)","type":"number","unit":"a","min":0,"aria_label":"Branchendurchschnittliche Lebensdauer des Produkts oder Materials X (optional, A.3.2)"},{"key":"pct_reuo","label":"PREUO(X) (A.5)","type":"derived","expr":"m_reuo / m_to * 100"},{"key":"pct_reco","label":"PRECO(X) (A.6)","type":"derived","expr":"if(traceable_recycling == true, m_reco / m_to * 100, 0)"},{"key":"pct_reno","label":"PRENO(X) (A.7)","type":"derived","expr":"m_reno / m_to * 100"},{"key":"pct_linear","label":"linear (%)","type":"derived","expr":"100 - pct_reuo - pct_reco - pct_reno"},{"key":"m_linear","label":"linear (kg)","type":"derived","expr":"m_to - m_reuo - if(traceable_recycling == true, m_reco, 0) - m_reno"},{"key":"rlp","label":"RLP(X) (A.4)","type":"derived","expr":"t_lp / t_ialp"},{"key":"balanced","label":"100 %-Bilanz","type":"derived","expr":"if(m_reuo + if(traceable_recycling == true, m_reco, 0) + m_reno <= m_to, 1, 0)","display":"badge","value_labels":{"0":"zirkuläre Massen übersteigen mTO(X)","1":"bilanziert (zirkulär ≤ Gesamt)"}}],"footer":["outflows_count","m_to_total","pct_reuo_agg","pct_reco_agg","pct_reno_agg","pct_linear_out_agg","outflows_unbalanced","outflows_untraceable"],"note":"             The following three core circularity indicators are intended to represent outflows that are mutually\n             exclusive and represent the circular outflows:\n             — components and products that are reused (see A.3.3);\n             — per cent recycled material derived from outflow (see A.3.4),\n             — products and materials for renewable recirculation (see A.3.5).\n             The remaining outflows are considered as linear and do not count towards circularity. The linear (non-\n             circular) outflow can be calculated by subtracting the circular outflows from 100 %.              If traceable recyclability data are not available for a specific resource outflow, 0 % should be recorded. Eine Zeile ohne gesetztes „Recyclingdaten rückverfolgbar“ rechnet mit PRECO(X) = 0 % (iso59020-J-7); RLP(X) bleibt leer ohne die optionalen Lebensdauern (kein Mittelwert über Zeilen — iso59020-J-8). Die Einzelfelder mTO_X / mREUO_X / mRECO_X / mRENO_X / tLP_X / tIALP_X / pct_linear_outflow bleiben (iso59020-D-11 … D-17); Gleichungen A.4 – A.7 und CR-015 … CR-019 → iso59020-R-1 / G-3."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'outflows') AND w.code = 'ISO-59020-06' AND s.code = 'ISO-59020';
