SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'outflows_count', 'Anzahl erfasster Abflüsse X', 'number', NULL, false, 'A.3.1', 'Plan 3: Ausgabe der Gleichung ISO-59020-06-D1 — count_rows über outflows.', 'imported_unverified', '             The sum of the circular outflows and the remaining non-circular outflows represent 100 % of the resource
             outflows from the system in focus, see Figure A.2. The resource outflow circularity indicators specified in
             A.3.3, A.3.4 and A.3.5 shall be calculated and documented. In cases where the circularity indicator is not
             relevant, it can be counted at value zero. The circularity indicators for each outflow can be calculated and
             reported individually or they can be aggregated, based on goal and scope.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'outflows_count') AND w.code = 'ISO-59020-06' AND s.code = 'ISO-59020';
