SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'm_reuo_total', 'Σ mREUO(X)', 'number', 'kg', false, 'A.3.3', 'Plan 3: Ausgabe der Gleichung ISO-59020-06-D3 — sum_rows über outflows.m_reuo.', 'imported_unverified', '             where

                       PREUO( X )               is the actual reused products and components derived from outflow (X), in %;

