SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'm_reno_total', 'Σ mRENO(X)', 'number', 'kg', false, 'A.3.5', 'Plan 3: Ausgabe der Gleichung ISO-59020-06-D5 — sum_rows über outflows.m_reno.', 'imported_unverified', '             The calculation of the circularity indicator is performed by applying Formula (A.7):

                                    mRENO( X )            
                      PRENO( X ) =                         ⋅100                                                                    (A.7)
                                    mTO X                 
                                        ( )               
             where

                       PRENO( X )               is the per cent actual recirculation of outflow (X) in the biological cycle, in %;

                       mRENO( X )               is the mass of outflow (X) that is renewable recirculation, in kg or other mass unit;

                       mTO( X )                 is the total mass of outflow (X), in kg or other mass unit.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_reno_total') AND w.code = 'ISO-59020-06' AND s.code = 'ISO-59020';
