             The remaining outflows are considered as linear and do not count towards circularity. The linear (non-
             circular) outflow can be calculated by subtracting the circular outflows from 100 %.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'm_linear_out_total') AND w.code = 'ISO-59020-06' AND s.code = 'ISO-59020';
