SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'G'), 'outflows_unbalanced', 'Abflüsse mit verletzter 100 %-Bilanz', 'number', NULL, false, 'A.3.1', 'Plan 3: Ausgabe der Gleichung ISO-59020-06-D11 — Zeilen mit balanced = 0 (zirkuläre Massen > mTO); CR-019 → iso59020-G-3.', 'imported_unverified', '             The sum of the circular outflows and the remaining non-circular outflows represent 100 % of the resource
