SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'energy_flows', 'Energieflüsse X (je Fluss: Einheit, EIRENE, EORENE, EITE, EOTE; PECONRE nach A.8)', 'json', NULL, false, 'A.4.2, Formula (A.8)', 'Plan 3: Zeilen je Energiefluss X mit Formula (A.8) je Zeile und der Einheitsprüfung gegen energy_unit_common („A common suitable measurement unit (e.g. MJ, kWh) shall be selected“); Σ / gewichteter Anteil → ISO-59020-07-D1 … D7. Die Einzelfelder bleiben (iso59020-D-18 … D-21).', 'imported_unverified', '             A common suitable measurement unit (e.g. MJ, kWh) shall be selected for the quantification of all relevant
             energies (e.g. thermal, electrical) that are involved in the measurement. —                        PECONRE( X )                 is the average energy (X) consumed that is renewable energy, in %;

                       E IRENE( X )                 is the renewable energy (X) inflow, in MJ (or in kWh);

                       EORENE( X )                  is the renewable energy (X) outflow, in MJ (or in kWh);

                       E ITE( X )                   is the total energy (X) inflow, in MJ (or in kWh);

                       EOTE( X )                    is the total energy (X) outflow, in MJ (or in kWh).', 'register', '{"title":"Energieflüsse X (energy flows, Annex A.4.2)","subtitle":"Je Energiefluss X eine Zeile: erneuerbarer Zu-/Abfluss EIRENE / EORENE und gesamter Zu-/Abfluss EITE / EOTE in der gemeinsamen Einheit (MJ oder kWh, A.4.2); PECONRE(X) nach Formula (A.8) je Zeile","add_label":"+ Energiefluss","placement":"section","columns":[{"key":"label","label":"Energiefluss X","type":"text","required":true,"aria_label":"Bezeichnung des Energieflusses X"},{"key":"unit","label":"Einheit","type":"enum","required":true,"options":["MJ","kWh"],"aria_label":"Energieeinheit der Zeile (MJ oder kWh)"},{"key":"ei_rene","label":"EIRENE(X)","type":"number","required":true,"min":0,"aria_label":"Erneuerbarer Energiezufluss X"},{"key":"eo_rene","label":"EORENE(X)","type":"number","required":true,"min":0,"aria_label":"Erneuerbarer Energieabfluss X"},{"key":"ei_te","label":"EITE(X)","type":"number","required":true,"min":0,"aria_label":"Gesamter Energiezufluss X"},{"key":"eo_te","label":"EOTE(X)","type":"number","required":true,"min":0,"aria_label":"Gesamter Energieabfluss X"},{"key":"net_consumed","label":"netto verbraucht","type":"derived","expr":"ei_te - eo_te"},{"key":"pct_econre","label":"PECONRE(X) (A.8)","type":"derived","expr":"(ei_rene - eo_rene) / (ei_te - eo_te) * 100"},{"key":"unit_ok","label":"Einheit","type":"derived","expr":"if(unit == energy_unit_common, 1, 0)","display":"badge","value_labels":{"0":"Einheit ≠ energy_unit_common (oder nicht gewählt)","1":"gemeinsame Einheit"}}],"footer":["energy_flows_count","ei_te_total","eo_te_total","pct_econre_agg","energy_unit_mismatch"],"note":"             A common suitable measurement unit (e.g. MJ, kWh) shall be selected for the quantification of all relevant\n             energies (e.g. thermal, electrical) that are involved in the measurement. Die Zeile gilt als abweichend, solange die gemeinsame Einheit dieses Arbeitsblatts (energy_unit_common) nicht gewählt ist. Formula (A.8) druckt „⋅1000“, die Legende „in %“ — die Zeile rechnet · 100 (iso59020-U-2). Die Einzelfelder EIRENE_X / EORENE_X / EITE_X / EOTE_X bleiben (iso59020-D-18 … D-21); Gleichung A.8 und CR-020 → iso59020-R-1 / G-1."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
