SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'pct_econre_agg', 'Erneuerbarer Anteil der netto verbrauchten Energie über alle Flüsse', 'number', '%', false, 'A.4.2, Annex G.2', 'Plan 3: Ausgabe der Gleichung ISO-59020-07-D6 — (Σ EIRENE − Σ EORENE) / (Σ EITE − Σ EOTE) · 100 — Formula (A.8) über die Summen (iso59020-J-1).', 'imported_unverified', '             The calculation of the circularity indicator is performed by applying Formula (A.8):

