SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'data_sources', 'Elementarkomponenten und Datenquellen (je Komponente: Quelle, Einordnung nach §7.6.2, Rückverfolgbarkeit, Dokumentation, Begründung)', 'json', NULL, false, '§7.6.1.2, §7.6.2', 'Plan 3: Zeilen je Elementarkomponente („the system in focus is subdivided into its elementary components … identification of data sources“) mit der §7.6.2-Einordnung; Anzahl → data_sources_count (ISO-59020-08-D1), nicht rückverfolgbar → data_sources_untraceable (-D2), sekundär / generisch / Hintergrund → -D3 … -D5. Die Einzelfelder bleiben (iso59020-D-22 … D-24).', 'imported_unverified', '             To enable a systematic data acquisition, and to provide transparency to the acquired data, it is recommended
             that the system in focus is subdivided into its elementary components for which data acquisition can be
             practically executed, such as the identification of data sources for general inflows and outflows. —              — strive towards being specific data based on primary data;
             — be categorized as foreground or background, primary or secondary, specific or generic (secondary and
               generic data should be conservatively applied and not overstate the circularity);', 'register', '{"title":"Elementarkomponenten und Datenquellen (§7.6.1.2 Step A, §7.6.2)","subtitle":"Je Elementarkomponente des Systems eine Zeile mit ihrer Datenquelle, der Einordnung nach §7.6.2 (primär/sekundär, Vordergrund/Hintergrund, spezifisch/generisch), Rückverfolgbarkeit, Dokumentation und Begründung","add_label":"+ Komponente / Datenquelle","placement":"section","columns":[{"key":"component","label":"Elementarkomponente","type":"text","required":true,"aria_label":"Elementarkomponente des Systems im Fokus"},{"key":"source","label":"Datenquelle","type":"text","aria_label":"Datenquelle der Komponente"},{"key":"origin","label":"primär / sekundär","type":"enum","required":true,"options":["primary","secondary"],"option_labels":{"primary":"primary (Primärdaten)","secondary":"secondary (Sekundärdaten)"},"aria_label":"Primär- oder Sekundärdaten"},{"key":"scope","label":"Vordergrund / Hintergrund","type":"enum","required":true,"options":["foreground","background"],"option_labels":{"foreground":"foreground","background":"background"},"aria_label":"Vordergrund- oder Hintergrunddaten"},{"key":"specificity","label":"spezifisch / generisch","type":"enum","required":true,"options":["specific","generic"],"option_labels":{"specific":"specific","generic":"generic"},"aria_label":"Spezifische oder generische Daten"},{"key":"traceable","label":"rückverfolgbar","type":"boolean","aria_label":"Daten rückverfolgbar und verifizierbar"},{"key":"documented","label":"dokumentiert","type":"boolean","aria_label":"Mit ausreichender Dokumentation geliefert (§7.6.2)"},{"key":"justification","label":"Begründung","type":"text","aria_label":"Begründung, wie gut die Kriterien erfüllt sind (§7.6.2)"},{"key":"conservative","label":"konservativ anwenden","type":"derived","expr":"if(origin == ''secondary'' OR specificity == ''generic'', 1, 0)","display":"badge","value_labels":{"0":"","1":"sekundär / generisch — konservativ anwenden, Zirkularität nicht überschätzen"}}],"footer":["data_sources_count","data_sources_untraceable","data_sources_secondary","data_sources_generic","data_sources_background"],"note":"             To enable a systematic data acquisition, and to provide transparency to the acquired data, it is recommended\n             that the system in focus is subdivided into its elementary components for which data acquisition can be\n             practically executed, such as the identification of data sources for general inflows and outflows.              — strive towards being specific data based on primary data;\n             — be categorized as foreground or background, primary or secondary, specific or generic (secondary and\n               generic data should be conservatively applied and not overstate the circularity); Die Einzelfelder system_breakdown_done / data_category / data_traceability bleiben (iso59020-D-22 … D-24); die drei Einordnungsspalten teilen prod’s Aufzählung data_category in die drei gedruckten Paare (iso59020-J-4)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'data_sources') AND w.code = 'ISO-59020-08' AND s.code = 'ISO-59020';
