SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'complementary_methods', 'Komplementäre Methoden (Annex C; je Methode: Norm, Wirkungsaspekt, Bezug, Ergebnis)', 'json', NULL, false, '§3.3.7, §7.3.3, Annex C', 'Plan 3: Zeilen je komplementärer Methode („method, approach or standard that is used together with circularity measurement“); Anzahl → complementary_methods_count (ISO-59020-09-D1). Das Textfeld complementary_method bleibt (iso59020-D-25).', 'imported_unverified', '             3.3.7
             complementary method
             method, approach or standard that is used together with circularity measurement (3.3.2) to provide a
